namespace sv_65fed25e50474c299d96318749426fa7.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);

public record NotificationPrefs(
    bool EmailNotifications,
    bool PushNotifications,
    bool WeeklyDigest,
    List<string> MutedChannels);

public record SecuritySettings(
    bool TwoFactorEnabled,
    DateTime? LastPasswordChange,
    List<ActiveSession> Sessions);

public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);

public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@page "/settings"
@rendermode InteractiveServer
@using sv_65fed25e50474c299d96318749426fa7.Services
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<h1 class="mb-4">Settings</h1>

@if (_loading)
{
    <div class="d-flex justify-content-center py-5">
        <div class="spinner-border text-primary" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else
{
    <div class="settings-layout">
        <!-- Left sidebar navigation -->
        <nav class="settings-sidebar" role="tablist" aria-label="Settings sections">
            @foreach (var section in _sections)
            {
                <button type="button"
                        class="settings-nav-item @(section == _activeSection ? "active" : "")"
                        role="tab"
                        aria-selected="@(section == _activeSection)"
                        @onclick="() => _activeSection = section">
                    <span class="settings-nav-icon">@GetSectionIcon(section)</span>
                    @section
                </button>
            }
        </nav>

        <!-- Main content area -->
        <div class="settings-content" role="tabpanel">
            @if (_activeSection == "Profile")
            {
                @RenderProfileSection()
            }
            else if (_activeSection == "Notifications")
            {
                @RenderNotificationsSection()
            }
            else if (_activeSection == "Security")
            {
                @RenderSecuritySection()
            }
            else if (_activeSection == "Appearance")
            {
                @RenderAppearanceSection()
            }
        </div>
    </div>
}

@* Toast notification *@
@if (_toastVisible)
{
    <div class="settings-toast @(_toastIsError ? "toast-error" : "toast-success")" role="alert">
        <span>@_toastMessage</span>
        <button type="button" class="btn-close btn-close-white btn-sm" @onclick="() => _toastVisible = false"></button>
    </div>
}

@* Session revoke confirmation modal *@
@if (_showRevokeConfirm)
{
    <div class="modal-backdrop show" @onclick="() => _showRevokeConfirm = false"></div>
    <div class="modal d-block" tabindex="-1" role="dialog">
        <div class="modal-dialog modal-dialog-centered">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Revoke Session</h5>
                    <button type="button" class="btn-close" @onclick="() => _showRevokeConfirm = false"></button>
                </div>
                <div class="modal-body">
                    <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke?.Device</strong> from <strong>@_sessionToRevoke?.Location</strong>?</p>
                    <p class="text-muted mb-0">This will sign out the device immediately.</p>
                </div>
                <div class="modal-footer">
                    <button type="button" class="btn btn-secondary" @onclick="() => _showRevokeConfirm = false">Cancel</button>
                    <button type="button" class="btn btn-danger" @onclick="ConfirmRevokeSession" disabled="@_revoking">
                        @if (_revoking)
                        {
                            <span class="spinner-border spinner-border-sm me-1"></span>
                        }
                        Revoke
                    </button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    private static readonly string[] _sections = ["Profile", "Notifications", "Security", "Appearance"];
    private static readonly string[] _availableChannels = ["General", "Announcements", "Engineering", "Design", "Marketing", "Support"];
    private static readonly string[] _availableLanguages = ["English", "Spanish", "French", "German", "Japanese", "Portuguese", "Chinese"];

    private string _activeSection = "Profile";
    private bool _loading = true;

    // Toast state
    private bool _toastVisible;
    private string _toastMessage = "";
    private bool _toastIsError;
    private CancellationTokenSource? _toastCts;

    // Profile state
    private UserProfile? _savedProfile;
    private string _profileDisplayName = "";
    private string _profileEmail = "";
    private string _profileAvatarUrl = "";
    private string _profileBio = "";
    private bool _savingProfile;

    // Notifications state
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = new();
    private bool _savingNotifications;

    // Security state
    private SecuritySettings? _securitySettings;
    private bool _changePasswordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _changingPassword;
    private bool _showRevokeConfirm;
    private ActiveSession? _sessionToRevoke;
    private bool _revoking;

    // Appearance state
    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private bool _savingAppearance;

    protected override async Task OnInitializedAsync()
    {
        try
        {
            var profileTask = SettingsService.GetProfileAsync();
            var notifTask = SettingsService.GetNotificationPrefsAsync();
            var securityTask = SettingsService.GetSecuritySettingsAsync();
            var appearanceTask = SettingsService.GetAppearanceAsync();

            await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

            var profile = profileTask.Result;
            _savedProfile = profile;
            ApplyProfile(profile);

            var notif = notifTask.Result;
            _emailNotifications = notif.EmailNotifications;
            _pushNotifications = notif.PushNotifications;
            _weeklyDigest = notif.WeeklyDigest;
            _mutedChannels = new HashSet<string>(notif.MutedChannels);

            _securitySettings = securityTask.Result;

            var appearance = appearanceTask.Result;
            _theme = appearance.Theme;
            _fontSize = appearance.FontSize;
            _language = appearance.Language;
            _compactMode = appearance.CompactMode;
        }
        catch
        {
            ShowToast("Failed to load settings.", isError: true);
        }
        finally
        {
            _loading = false;
        }
    }

    private void ApplyProfile(UserProfile profile)
    {
        _profileDisplayName = profile.DisplayName;
        _profileEmail = profile.Email;
        _profileAvatarUrl = profile.AvatarUrl;
        _profileBio = profile.Bio;
    }

    // ----- Profile -----

    private RenderFragment RenderProfileSection() => __builder =>
    {
        <h2 class="settings-section-title">Profile</h2>
        <p class="text-muted">Manage your personal information and public profile.</p>

        <div class="row g-4">
            <div class="col-md-8">
                <div class="mb-3">
                    <label class="form-label" for="displayName">Display Name</label>
                    <input id="displayName" type="text" class="form-control" @bind="_profileDisplayName" />
                </div>
                <div class="mb-3">
                    <label class="form-label" for="email">Email</label>
                    <input id="email" type="email" class="form-control" @bind="_profileEmail" />
                </div>
                <div class="mb-3">
                    <label class="form-label" for="bio">Bio</label>
                    <textarea id="bio" class="form-control" rows="4" @bind="_profileBio"></textarea>
                </div>
            </div>
            <div class="col-md-4">
                <div class="avatar-preview-area text-center">
                    <label class="form-label">Avatar Preview</label>
                    <div class="avatar-frame mx-auto mb-2">
                        @if (!string.IsNullOrWhiteSpace(_profileAvatarUrl))
                        {
                            <img src="@_profileAvatarUrl" alt="Avatar" class="avatar-img" />
                        }
                        else
                        {
                            <div class="avatar-placeholder">
                                <span>👤</span>
                            </div>
                        }
                    </div>
                    <small class="text-muted text-break">@(_profileAvatarUrl ?? "No avatar URL set")</small>
                </div>
            </div>
        </div>

        <hr />

        <div class="d-flex gap-2">
            <button type="button" class="btn btn-primary" @onclick="SaveProfile" disabled="@_savingProfile">
                @if (_savingProfile)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Save Changes
            </button>
            <button type="button" class="btn btn-outline-secondary" @onclick="DiscardProfileChanges">
                Discard Changes
            </button>
        </div>
    };

    private async Task SaveProfile()
    {
        _savingProfile = true;
        try
        {
            var profile = new UserProfile(_profileDisplayName, _profileEmail, _profileAvatarUrl, _profileBio);
            await SettingsService.SaveProfileAsync(profile);
            _savedProfile = profile;
            ShowToast("Profile saved successfully.");
        }
        catch
        {
            ShowToast("Failed to save profile.", isError: true);
        }
        finally
        {
            _savingProfile = false;
        }
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
        {
            ApplyProfile(_savedProfile);
        }
    }

    // ----- Notifications -----

    private RenderFragment RenderNotificationsSection() => __builder =>
    {
        <h2 class="settings-section-title">Notifications</h2>
        <p class="text-muted">Choose how and when you receive notifications.</p>

        <div class="mb-4">
            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="emailNotif" @bind="_emailNotifications" />
                <label class="form-check-label" for="emailNotif">
                    <strong>Email Notifications</strong>
                    <br /><small class="text-muted">Receive important updates via email</small>
                </label>
            </div>

            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="pushNotif" @bind="_pushNotifications" />
                <label class="form-check-label" for="pushNotif">
                    <strong>Push Notifications</strong>
                    <br /><small class="text-muted">Get real-time push notifications on your devices</small>
                </label>
            </div>

            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="_weeklyDigest" />
                <label class="form-check-label" for="weeklyDigest">
                    <strong>Weekly Digest</strong>
                    <br /><small class="text-muted">Receive a weekly summary of activity</small>
                </label>
            </div>
        </div>

        <h5>Muted Channels</h5>
        <p class="text-muted">Select channels you want to mute.</p>
        <div class="row g-2 mb-4">
            @foreach (var channel in _availableChannels)
            {
                var ch = channel;
                <div class="col-sm-6 col-md-4">
                    <div class="form-check">
                        <input class="form-check-input darker-border-checkbox" type="checkbox" id="@($"ch-{ch}")"
                               checked="@_mutedChannels.Contains(ch)"
                               @onchange="(e) => ToggleMutedChannel(ch, (bool)(e.Value ?? false))" />
                        <label class="form-check-label" for="@($"ch-{ch}")">@ch</label>
                    </div>
                </div>
            }
        </div>

        <button type="button" class="btn btn-primary" @onclick="SaveNotifications" disabled="@_savingNotifications">
            @if (_savingNotifications)
            {
                <span class="spinner-border spinner-border-sm me-1"></span>
            }
            Save Preferences
        </button>
    };

    private void ToggleMutedChannel(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        _savingNotifications = true;
        try
        {
            var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
            await SettingsService.SaveNotificationPrefsAsync(prefs);
            ShowToast("Notification preferences saved.");
        }
        catch
        {
            ShowToast("Failed to save notification preferences.", isError: true);
        }
        finally
        {
            _savingNotifications = false;
        }
    }

    // ----- Security -----

    private RenderFragment RenderSecuritySection() => __builder =>
    {
        <h2 class="settings-section-title">Security</h2>
        <p class="text-muted">Manage your password, two-factor authentication, and active sessions.</p>

        <!-- Change Password -->
        <div class="card mb-4">
            <div class="card-header d-flex align-items-center justify-content-between"
                 style="cursor: pointer;"
                 @onclick="() => _changePasswordExpanded = !_changePasswordExpanded">
                <strong>Change Password</strong>
                <span class="expand-icon">@(_changePasswordExpanded ? "▲" : "▼")</span>
            </div>
            @if (_changePasswordExpanded)
            {
                <div class="card-body">
                    <div class="row">
                        <div class="col-md-6">
                            <div class="mb-3">
                                <label class="form-label" for="currentPwd">Current Password</label>
                                <input id="currentPwd" type="password" class="form-control" @bind="_currentPassword" />
                            </div>
                            <div class="mb-3">
                                <label class="form-label" for="newPwd">New Password</label>
                                <input id="newPwd" type="password" class="form-control" @bind="_newPassword" />
                            </div>
                            <div class="mb-3">
                                <label class="form-label" for="confirmPwd">Confirm Password</label>
                                <input id="confirmPwd" type="password" class="form-control" @bind="_confirmPassword"
                                       @oninput="StateHasChanged" />
                                @if (!string.IsNullOrEmpty(_confirmPassword) && _newPassword != _confirmPassword)
                                {
                                    <div class="text-danger mt-1"><small>Passwords do not match.</small></div>
                                }
                            </div>
                            <button type="button" class="btn btn-warning" @onclick="ChangePassword"
                                    disabled="@(_changingPassword || string.IsNullOrEmpty(_currentPassword) || string.IsNullOrEmpty(_newPassword) || _newPassword != _confirmPassword)">
                                @if (_changingPassword)
                                {
                                    <span class="spinner-border spinner-border-sm me-1"></span>
                                }
                                Update Password
                            </button>
                        </div>
                    </div>
                    @if (_securitySettings?.LastPasswordChange is not null)
                    {
                        <small class="text-muted mt-2 d-block">
                            Last changed: @_securitySettings.LastPasswordChange.Value.ToString("MMMM d, yyyy")
                        </small>
                    }
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="card mb-4">
            <div class="card-body d-flex align-items-center justify-content-between">
                <div>
                    <strong>Two-Factor Authentication</strong>
                    <br />
                    <span class="badge @(_securitySettings?.TwoFactorEnabled == true ? "bg-success" : "bg-secondary") mt-1">
                        @(_securitySettings?.TwoFactorEnabled == true ? "Enabled" : "Disabled")
                    </span>
                </div>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="twoFactor"
                           checked="@(_securitySettings?.TwoFactorEnabled == true)" disabled
                           title="Contact your administrator to change 2FA settings" />
                </div>
            </div>
        </div>

        <!-- Active Sessions -->
        <h5>Active Sessions</h5>
        @if (_securitySettings?.Sessions is { Count: > 0 })
        {
            <div class="table-responsive">
                <table class="table table-hover">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in _securitySettings.Sessions)
                        {
                            var isFirst = session == _securitySettings.Sessions[0];
                            <tr>
                                <td>
                                    @session.Device
                                    @if (isFirst)
                                    {
                                        <span class="badge bg-primary ms-1">Current</span>
                                    }
                                </td>
                                <td>@session.Location</td>
                                <td>@session.LastActive.ToString("MMM d, yyyy h:mm tt")</td>
                                <td>
                                    @if (!isFirst)
                                    {
                                        <button type="button" class="btn btn-outline-danger btn-sm"
                                                @onclick="() => PromptRevokeSession(session)">
                                            Revoke
                                        </button>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            </div>
        }
        else
        {
            <p class="text-muted">No active sessions found.</p>
        }
    };

    private async Task ChangePassword()
    {
        _changingPassword = true;
        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
            _changePasswordExpanded = false;
            ShowToast("Password updated successfully.");
        }
        catch
        {
            ShowToast("Failed to change password.", isError: true);
        }
        finally
        {
            _changingPassword = false;
        }
    }

    private void PromptRevokeSession(ActiveSession session)
    {
        _sessionToRevoke = session;
        _showRevokeConfirm = true;
    }

    private async Task ConfirmRevokeSession()
    {
        if (_sessionToRevoke is null) return;
        _revoking = true;
        try
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            // Reload security settings to refresh the session list
            _securitySettings = await SettingsService.GetSecuritySettingsAsync();
            _showRevokeConfirm = false;
            _sessionToRevoke = null;
            ShowToast("Session revoked.");
        }
        catch
        {
            ShowToast("Failed to revoke session.", isError: true);
        }
        finally
        {
            _revoking = false;
        }
    }

    // ----- Appearance -----

    private RenderFragment RenderAppearanceSection() => __builder =>
    {
        <h2 class="settings-section-title">Appearance</h2>
        <p class="text-muted">Customize how the application looks and feels.</p>

        <div class="row g-4">
            <div class="col-md-6">
                <!-- Theme -->
                <div class="mb-4">
                    <label class="form-label fw-bold">Theme</label>
                    <div>
                        @foreach (var t in new[] { "Light", "Dark", "System" })
                        {
                            var theme = t;
                            <div class="form-check form-check-inline">
                                <input class="form-check-input" type="radio" name="theme" id="@($"theme-{theme}")"
                                       value="@theme" checked="@(_theme == theme)"
                                       @onchange="() => _theme = theme" />
                                <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                            </div>
                        }
                    </div>
                </div>

                <!-- Font Size -->
                <div class="mb-4">
                    <label class="form-label fw-bold">Font Size</label>
                    <div>
                        @foreach (var size in new[] { "Small", "Medium", "Large" })
                        {
                            var s = size;
                            <div class="form-check form-check-inline">
                                <input class="form-check-input" type="radio" name="fontSize" id="@($"fs-{s}")"
                                       value="@s" checked="@(_fontSize == s)"
                                       @onchange="() => _fontSize = s" />
                                <label class="form-check-label" for="@($"fs-{s}")">@s</label>
                            </div>
                        }
                    </div>
                </div>

                <!-- Language -->
                <div class="mb-4">
                    <label class="form-label fw-bold" for="language">Language</label>
                    <select id="language" class="form-select" @bind="_language">
                        @foreach (var lang in _availableLanguages)
                        {
                            <option value="@lang">@lang</option>
                        }
                    </select>
                </div>

                <!-- Compact Mode -->
                <div class="mb-4">
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                        <label class="form-check-label" for="compactMode">
                            <strong>Compact Mode</strong>
                            <br /><small class="text-muted">Reduce spacing for a denser layout</small>
                        </label>
                    </div>
                </div>

                <button type="button" class="btn btn-primary" @onclick="SaveAppearance" disabled="@_savingAppearance">
                    @if (_savingAppearance)
                    {
                        <span class="spinner-border spinner-border-sm me-1"></span>
                    }
                    Save
                </button>
            </div>

            <!-- Live Preview -->
            <div class="col-md-6">
                <label class="form-label fw-bold">Live Preview</label>
                <div class="appearance-preview @GetPreviewClasses()">
                    <div class="preview-header">
                        <strong>Preview</strong>
                    </div>
                    <div class="preview-body">
                        <p>This is a sample paragraph showing how your selected appearance settings will look.</p>
                        <button type="button" class="btn btn-sm btn-primary">Sample Button</button>
                        <span class="badge bg-info ms-2">Badge</span>
                    </div>
                    <div class="preview-footer text-muted">
                        Theme: @_theme · Font: @_fontSize · Lang: @_language @(_compactMode ? " · Compact" : "")
                    </div>
                </div>
            </div>
        </div>
    };

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add(_theme.ToLowerInvariant() switch
        {
            "dark" => "preview-dark",
            "light" => "preview-light",
            _ => "preview-light"
        });
        classes.Add(_fontSize.ToLowerInvariant() switch
        {
            "small" => "preview-font-sm",
            "large" => "preview-font-lg",
            _ => "preview-font-md"
        });
        if (_compactMode) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }

    private async Task SaveAppearance()
    {
        _savingAppearance = true;
        try
        {
            var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
            await SettingsService.SaveAppearanceAsync(settings);
            ShowToast("Appearance settings saved.");
        }
        catch
        {
            ShowToast("Failed to save appearance settings.", isError: true);
        }
        finally
        {
            _savingAppearance = false;
        }
    }

    // ----- Helpers -----

    private static string GetSectionIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };

    private async void ShowToast(string message, bool isError = false)
    {
        _toastCts?.Cancel();
        _toastCts = new CancellationTokenSource();
        var token = _toastCts.Token;

        _toastMessage = message;
        _toastIsError = isError;
        _toastVisible = true;
        StateHasChanged();

        try
        {
            await Task.Delay(4000, token);
            _toastVisible = false;
            StateHasChanged();
        }
        catch (TaskCanceledException)
        {
            // Toast was replaced by a newer one
        }
    }
}

