+                                <input class="form-check-input" type="radio" name="fontSize" id="@($"fs-{s}")"
+                                       value="@s" checked="@(_fontSize == s)"
+                                       @onchange="() => _fontSize = s" />
+                                <label class="form-check-label" for="@($"fs-{s}")">@s</label>
+                            </div>
+                        }
+                    </div>
+                </div>
+
+                <!-- Language -->
+                <div class="mb-4">
+                    <label class="form-label fw-bold" for="language">Language</label>
+                    <select id="language" class="form-select" @bind="_language">
+                        @foreach (var lang in _availableLanguages)
+                        {
+                            <option value="@lang">@lang</option>
+                        }
+                    </select>
+                </div>
+
+                <!-- Compact Mode -->
+                <div class="mb-4">
+                    <div class="form-check form-switch">
+                        <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
+                        <label class="form-check-label" for="compactMode">
+                            <strong>Compact Mode</strong>
+                            <br /><small class="text-muted">Reduce spacing for a denser layout</small>
+                        </label>
+                    </div>
+                </div>
+
+                <button type="button" class="btn btn-primary" @onclick="SaveAppearance" disabled="@_savingAppearance">
+                    @if (_savingAppearance)
+                    {
+                        <span class="spinner-border spinner-border-sm me-1"></span>
+                    }
+                    Save
+                </button>
+            </div>
+
+            <!-- Live Preview -->
+            <div class="col-md-6">
+                <label class="form-label fw-bold">Live Preview</label>
+                <div class="appearance-preview @GetPreviewClasses()">
+                    <div class="preview-header">
+                        <strong>Preview</strong>
+                    </div>
+                    <div class="preview-body">
+                        <p>This is a sample paragraph showing how your selected appearance settings will look.</p>
+                        <button type="button" class="btn btn-sm btn-primary">Sample Button</button>
+                        <span class="badge bg-info ms-2">Badge</span>
+                    </div>
+                    <div class="preview-footer text-muted">
+                        Theme: @_theme · Font: @_fontSize · Lang: @_language @(_compactMode ? " · Compact" : "")
+                    </div>
+                </div>
+            </div>
+        </div>
+    };
+
+    private string GetPreviewClasses()
+    {
+        var classes = new List<string>();
+        classes.Add(_theme.ToLowerInvariant() switch
+        {
+            "dark" => "preview-dark",
+            "light" => "preview-light",
+            _ => "preview-light"
+        });
+        classes.Add(_fontSize.ToLowerInvariant() switch
+        {
+            "small" => "preview-font-sm",
+            "large" => "preview-font-lg",
+            _ => "preview-font-md"
+        });
+        if (_compactMode) classes.Add("preview-compact");
+        return string.Join(" ", classes);
+    }
+
+    private async Task SaveAppearance()
+    {
+        _savingAppearance = true;
+        try
+        {
+            var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
+            await SettingsService.SaveAppearanceAsync(settings);
+            ShowToast("Appearance settings saved.");
+        }
+        catch
+        {
+            ShowToast("Failed to save appearance settings.", isError: true);
+        }
+        finally
+        {
+            _savingAppearance = false;
+        }
+    }
+
+    // ----- Helpers -----
+
+    private static string GetSectionIcon(string section) => section switch
+    {
+        "Profile" => "👤",
+        "Notifications" => "🔔",
+        "Security" => "🔒",
+        "Appearance" => "🎨",
+        _ => "⚙️"
+    };
+
+    private async void ShowToast(string message, bool isError = false)
+    {
+        _toastCts?.Cancel();
+        _toastCts = new CancellationTokenSource();
+        var token = _toastCts.Token;
+
+        _toastMessage = message;
+        _toastIsError = isError;
+        _toastVisible = true;
+        StateHasChanged();
+
+        try
+        {
+            await Task.Delay(4000, token);
+            _toastVisible = false;
+            StateHasChanged();
+        }
+        catch (TaskCanceledException)
+        {
+            // Toast was replaced by a newer one
+        }
+    }
+}
+

toolArgs.file_text:
/* Layout */
.settings-layout {
    display: flex;
    gap: 2rem;
    min-height: 600px;
}

.settings-sidebar {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
    min-width: 200px;
    border-right: 1px solid #dee2e6;
    padding-right: 1rem;
}

.settings-nav-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1rem;
    border: none;
    background: none;
    border-radius: 0.5rem;
    text-align: left;
    font-size: 0.95rem;
    color: #495057;
    cursor: pointer;
    transition: background-color 0.15s, color 0.15s;
    width: 100%;
}

.settings-nav-item:hover {
    background-color: #f0f0f0;
}

.settings-nav-item.active {
    background-color: #e7f1ff;
    color: #0d6efd;
    font-weight: 600;
}

.settings-nav-icon {
    font-size: 1.15rem;
    width: 1.5rem;
    text-align: center;
}

.settings-content {
    flex: 1;
    min-width: 0;
}

.settings-section-title {
    font-size: 1.5rem;
    margin-bottom: 0.25rem;
}

/* Avatar */
.avatar-preview-area {
    padding: 1rem;
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    background: #fafafa;
}

.avatar-frame {
    width: 120px;
    height: 120px;
    border-radius: 50%;
    overflow: hidden;
    border: 3px solid #dee2e6;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #fff;
}

.avatar-img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.avatar-placeholder {
    font-size: 3rem;
    color: #adb5bd;
}

/* Expand icon */
.expand-icon {
    font-size: 0.75rem;
    color: #6c757d;
}

/* Toast */
.settings-toast {
    position: fixed;
    bottom: 1.5rem;
    right: 1.5rem;
    padding: 0.75rem 1.25rem;
    border-radius: 0.5rem;
    color: #fff;
    display: flex;
    align-items: center;
    gap: 1rem;
    z-index: 1080;
    box-shadow: 0 0.25rem 1rem rgba(0, 0, 0, 0.2);
    animation: toast-slide-in 0.3s ease;
}

.toast-success {
    background-color: #198754;
}

.toast-error {
    background-color: #dc3545;
}

@keyframes toast-slide-in {
    from {
        transform: translateY(1rem);
        opacity: 0;
    }
    to {
        transform: translateY(0);
        opacity: 1;
    }
}

/* Appearance preview */
.appearance-preview {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    overflow: hidden;
    transition: all 0.2s ease;
}

.preview-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid inherit;
}

.preview-body {
    padding: 1rem;
}

.preview-footer {
    padding: 0.5rem 1rem;
    border-top: 1px solid inherit;
    font-size: 0.8rem;
}

/* Preview theme variants */
.preview-light {
    background-color: #ffffff;
    color: #212529;
    border-color: #dee2e6;
}

.preview-light .preview-header {
    background-color: #f8f9fa;
    border-color: #dee2e6;
}

.preview-light .preview-footer {
    background-color: #f8f9fa;
    border-color: #dee2e6;
}

.preview-dark {
    background-color: #1e1e2e;
    color: #e0e0e0;
    border-color: #444;
}

.preview-dark .preview-header {
    background-color: #2a2a3d;
    border-color: #444;
}

.preview-dark .preview-footer {
    background-color: #2a2a3d;
    border-color: #444;
    color: #999;
}

/* Preview font sizes */
.preview-font-sm {
    font-size: 0.8rem;
}

.preview-font-md {
    font-size: 1rem;
}

.preview-font-lg {
    font-size: 1.2rem;
}

/* Preview compact */
.preview-compact .preview-header {
    padding: 0.4rem 0.75rem;
}

.preview-compact .preview-body {
    padding: 0.5rem 0.75rem;
}

.preview-compact .preview-body p {
    margin-bottom: 0.25rem;
}

.preview-compact .preview-footer {
    padding: 0.3rem 0.75rem;
}

/* Responsive */
@media (max-width: 768px) {
    .settings-layout {
        flex-direction: column;
    }

    .settings-sidebar {
        flex-direction: row;
        overflow-x: auto;
        border-right: none;
        border-bottom: 1px solid #dee2e6;
        padding-right: 0;
        padding-bottom: 0.5rem;
        min-width: unset;
    }

    .settings-nav-item {
        white-space: nowrap;
    }
}

